<script setup lang="ts">
const {user,restore,cart,loadCart,saveCart,api,money,message}=useMarketplace()
const busy=ref(false),error=ref(''),ready=ref(false),confirmed=ref(false)
const form=reactive({name:'',phone:'',address:'',postalCode:'',note:''})
const total=computed(()=>cart.value.reduce((s,i)=>s+Number(i.price)*i.quantity,0))
onMounted(async()=>{loadCart();await restore();Object.assign(form,{name:user.value?.name||'',phone:user.value?.phone||'',address:user.value?.address||''});ready.value=true})
async function submit(){if(busy.value||!confirmed.value)return;busy.value=true;error.value='';try{const order:any=await api('/api/orders',{method:'POST',body:{...form,items:cart.value.map(i=>({productId:i.id,quantity:i.quantity}))}});cart.value=[];saveCart();await navigateTo(`/orders/${order.id}`)}catch(e){error.value=message(e)}finally{busy.value=false}}
useHead({title:'ثبت سفارش | پارتلی'})
</script>
<template><section class="shell py-12"><h1 class="market-title">اطلاعات ارسال و ثبت سفارش</h1><p v-if="!ready" class="market-empty">در حال آماده‌سازی…</p><div v-else-if="!user" class="market-panel market-empty">برای ثبت سفارش وارد شوید. سبد خرید شما حفظ می‌شود.<NuxtLink to="/login" class="market-primary mt-5">ورود / ثبت‌نام</NuxtLink></div><div v-else-if="!cart.length" class="market-panel market-empty">سبد خرید خالی است. <NuxtLink to="/catalog" class="text-orange">انتخاب کالا</NuxtLink></div><form v-else class="mt-8 grid gap-6 lg:grid-cols-[1fr_360px]" @submit.prevent="submit"><div class="market-panel"><h2 class="mb-6 text-lg font-bold">نشانی گیرنده</h2><label class="market-label">نام گیرنده<input v-model="form.name" required maxlength="100" autocomplete="name" class="market-input"></label><label class="market-label">تلفن تماس<input v-model="form.phone" required type="tel" pattern="[+0-9 ()\-]{7,30}" autocomplete="tel" class="market-input" dir="ltr"></label><label class="market-label">نشانی کامل<textarea v-model="form.address" required maxlength="2000" autocomplete="street-address" rows="4" class="market-input" /></label><label class="market-label">کد پستی ۱۰ رقمی<input v-model="form.postalCode" required pattern="[0-9]{10}" inputmode="numeric" autocomplete="postal-code" class="market-input" dir="ltr"></label><label class="market-label">توضیحات سفارش (اختیاری)<textarea v-model="form.note" maxlength="2000" class="market-input" /></label></div><aside class="market-panel h-fit"><h2 class="mb-6 text-lg font-bold">خلاصه سفارش</h2><div v-for="item in cart" :key="item.id" class="mb-4 flex justify-between gap-3 text-xs leading-6"><span>{{item.name}} × {{item.quantity}}</span><span class="shrink-0">{{money(Number(item.price)*item.quantity)}}</span></div><div class="my-5 flex justify-between border-t pt-5 text-sm font-bold"><span>جمع کالاها</span><span>{{money(total)}}</span></div><p class="mb-4 text-xs leading-6 text-slate-500">هزینه ارسال: ۰ تومان. روش پرداخت این نسخه فقط پرداخت در محل است؛ هیچ پرداخت اینترنتی انجام نمی‌شود. قیمت روز کالاها هنگام ثبت سفارش توسط سرور محاسبه می‌شود.</p><label class="mb-5 flex items-start gap-2 text-xs leading-6"><input v-model="confirmed" type="checkbox" required class="mt-1.5"><span>اطلاعات سفارش و <NuxtLink to="/returns" class="text-orange">شرایط خرید و مرجوعی</NuxtLink> را بررسی کرده‌ام.</span></label><div v-if="error" class="market-error" role="alert">{{error}}</div><button class="market-primary w-full" :disabled="busy||!confirmed">{{busy?'در حال ثبت سفارش…':'ثبت سفارش با پرداخت در محل'}}</button><NuxtLink to="/cart" class="mt-4 block text-center text-xs text-slate-500">بازگشت به سبد</NuxtLink></aside></form></section></template>
